  main :is(.lu-arch,.lu-rect,.lu-circle):not(.lu-noreveal) img{animation:lu-zoom linear both;animation-timeline:view();animation-range:entry 0% cover 45%}
  @keyframes lu-zoom{from{scale:1.18}to{scale:1}}
 }
 .lu-hero__title,.lu-phead h1,.lu-story-hero h1,.lu-pd-hero h1,.lu-book h1{animation:lu-rise .9s cubic-bezier(.2,.7,.2,1) both}
 @keyframes lu-rise{from{opacity:0;transform:translateY(1.2rem)}to{opacity:1;transform:none}}
}
